/**
 * Evidence registry for source-language fields that have been checked against
 * a primary-text digital edition. Presence here is deliberately narrower than
 * merely having a work title or passage locator.
 */

export const VERIFIED_SOURCE_CHECKED_ON = "2026-08-10" as const;
export const VERIFIED_SOURCE_LATEST_CHECKED_ON = "2026-08-24" as const;
export const VERIFIED_SOURCE_CURRENT_CHECKED_ON = "2026-08-26" as const;
export const VERIFIED_SOURCE_ACTIVE_CHECKED_ON = "2026-08-27" as const;
export const VERIFIED_SOURCE_COMPLETION_CHECKED_ON = "2026-08-28" as const;
export const VERIFIED_SOURCE_PUBLIC_UNHANDLED_CHECKED_ON = "2026-08-29" as const;
export const VERIFIED_SOURCE_CURATION_CHECKED_ON = "2026-08-30" as const;

export type VerifiedSourceOriginalField = "text" | "english";

export type VerifiedSourceUseBasis = Readonly<{
  kind: "public-domain" | "open-license" | "quotation-exception";
  zh: string;
  en: string;
}>;

export type VerifiedSourceReferenceLink = Readonly<{
  href: string;
  label: string;
  englishLabel: string;
}>;

export type VerifiedSourcePassage = Readonly<{
  id: string;
  originalField: VerifiedSourceOriginalField;
  checkedOn:
    | typeof VERIFIED_SOURCE_CHECKED_ON
    | typeof VERIFIED_SOURCE_LATEST_CHECKED_ON
    | typeof VERIFIED_SOURCE_CURRENT_CHECKED_ON
    | typeof VERIFIED_SOURCE_ACTIVE_CHECKED_ON
    | typeof VERIFIED_SOURCE_COMPLETION_CHECKED_ON
    | typeof VERIFIED_SOURCE_PUBLIC_UNHANDLED_CHECKED_ON
    | typeof VERIFIED_SOURCE_CURATION_CHECKED_ON;
  referenceEdition: Readonly<{
    zh: string;
    en: string;
  }>;
  /** Why the checked verbatim field can be included; separate from source accuracy. */
  useBasis: VerifiedSourceUseBasis;
  referenceLinks: readonly VerifiedSourceReferenceLink[];
}>;

